/bin/bash -lc "python3 -c 'import plan_review
for rel in sorted(plan_review._LEGACY_ASSETS):
    body=plan_review.legacy_asset_bytes(rel).decode(\"utf-8\")
    if \"larch_quiet_init\" in body or \"validate-design-tmpdir\" in body:
        qi=body.find(\"larch_quiet_init\"); vi=body.find(\"validate-design-tmpdir\")
        print(rel, \"quiet\", qi, \"validate\", vi, \"quiet_before_validate\", qi"'!=-1 and (vi==-1 or qi<vi))
        for i,l in enumerate(body.splitlines(),1):
            if "larch_quiet_init" in l or "validate-design-tmpdir" in l or "lib-quiet" in l or "lib-phase-driver" in l or "CLI=" in l:
                print(f"  {i}: {l}")
        print()'"'"

